.jquery-comments * {
	box-sizing: border-box;
	text-shadow: none;
}

.jquery-comments :where(a[href]:not(.tag), .main .comment .wrapper .truncated, #unmute-users+.separator, .video-timecode, .video-timecode-return), #flag-comment a {
	color: #ef4137
} 

.jquery-comments a[href]:not(.tag) {
	text-decoration: none;
}

.jquery-comments a[href]:not(.tag):hover {
	text-decoration: underline;
}

.jquery-comments .textarea, .jquery-comments input, .jquery-comments button {
	-webkit-appearance: none;
	-moz-appearance: none;
	-ms-appearance: none;
	appearance: none;

	vertical-align: top;
	border-radius: 0;
	margin: 0;
	padding: 0;
	border: 0;
	outline: 0;
	background: rgba(0, 0, 0, 0);
}

.jquery-comments button {
	vertical-align: inherit;
}

.jquery-comments .tag {
	color: inherit;
	font-size: 0.9em;
	line-height: 1.2em;
	background: #ddd;
	border: 1px solid #ccc;
	padding: 0.05em 0.4em;
	cursor: pointer;
	font-weight: normal;
	border-radius: 1em;
	transition: all 0.2s linear;
	white-space: nowrap;
	display: inline-block;
	text-decoration: none;
}

.jquery-comments .attachments .tag {
	white-space: normal;
	word-break: break-all;

	padding: 0.05em 0.5em;
	line-height: 1.3em;

	margin-top: 0.3em;
	margin-right: 0.5em;
}

.jquery-comments .attachments .tag > i:first-chil

.new-or-updated-comment {
    background-color: #f0f0f0;
    color: #000
}

.updated-votes {
    color: #000 !important
}

.highlighted-comment {
    background-color: #f0f0f0;
    color: #000
}

#muted-or-blocked-users {
    background-color: #e8e8e8;
    border: 1px solid #2c2a2d
}

#muted-or-blocked-users thead tr {
    border-bottom: 1px solid #2c2a2d
}

#muted-or-blocked-users thead th span {
    color: #4d4b4e;
    opacity: 1
}

.universal-pin {
    background-color: #d8d8d8;
    color: #000
}

.pinned {
    background-color: #e8e8e8;
    color: #000
}

#flag-comment {
    background-color: #e8e8e8;
    border: 1px solid #2c2a2d
}

#flag-comment .heading {
    border-bottom: 1px solid #2c2a2d
}

#flag-comment .close {
    color: #5d6b5e
}

#image-viewer {
    background-color: #e8e8e8;
    border: 3px solid #2c2a2d;
    color: #2c2a2d  
}

#image-viewer .controls {
    border-bottom: 3px solid #2c2a2d
}

#image-viewer .close, #image-viewer .info {
   color: #2c2a2d
}

#image-viewer .previous, #image-viewer .next {
    background-color: #2c2a2d;
    color: #b0b0b0
}

